{"script":"() => {
  // Try to close any overlay first
  const overlay = document.querySelector('[aria-label="关闭"]');
  if (overlay) overlay.click();

  // Get text of side panel for the reviews
  const sidePanel = document.querySelector('[role="main"]') || document.body;
  return {
    title: document.title,
    url: window.location.href,
    hasOverlay: !!document.querySelector('div[role="dialog"]'),
  };
}"}

